-- FAQ de Teclab, tanda 1 (28/11/2026): Seguridad Informática (221) y Data Science (218)
-- de 3 a 9 preguntas; Redes Informáticas (220) de 8 a 9. Textos aprobados por el usuario.
-- Fuentes: fichas oficiales de teclab.edu.ar, plan y certificados en D1 y conocimiento/teclab.md,
-- carreras/teclab/articulaciones-teclab.json; nombres de las carreras de Siglo 21 verificados
-- en 21.edu.ar/carreras-y-programas. Título de Data Science como en la ficha oficial y en D1
-- («Técnico Superior en Data Science»); conocimiento/teclab.md dice «en Ciencia de Datos
-- (Data Science)»: confirmar contra la resolución. Cada UPDATE exige el JSON actual: si cambió, no escribe.
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Data Science?","respuesta":"Estudiás análisis y visualización de datos, estadística, bases de datos, Big Data y Machine Learning. La formación combina procesamiento de información y programación para encontrar patrones y comunicar resultados."},{"pregunta":"¿Cuál es la diferencia entre Data Science y análisis de datos?","respuesta":"El análisis de datos ayuda a interpretar información y elaborar informes. Data Science incorpora además estadística, programación y modelos de Machine Learning para explorar patrones y realizar predicciones a partir de los datos."},{"pregunta":"¿Cuál es la salida laboral de Data Science?","respuesta":"La formación se vincula con tareas de análisis, visualización e inteligencia de negocio en empresas tecnológicas, consultoras y áreas que usan datos para tomar decisiones. También permite participar en proyectos de analítica de manera independiente."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas, laboratorios virtuales y actividades prácticas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Data Science, un título oficial con acreditación nacional. El plan contempla además el certificado intermedio de Asistente en Analítica de Datos."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con análisis y visualización de datos, procesamiento de datos y scripting en el primer cuatrimestre."},{"pregunta":"¿Hace falta saber mucha matemática?","respuesta":"No hace falta un nivel avanzado para empezar. Matemática y estadística se cursa en el segundo cuatrimestre y se aplica a problemas concretos de datos y predicciones."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Ciencia de Datos y con Ingeniería en Innovación y Desarrollo de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 218 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Data Science?","respuesta":"Estudiás análisis y visualización de datos, estadística, bases de datos, Big Data y Machine Learning. La formación combina procesamiento de información y programación para encontrar patrones y comunicar resultados."},{"pregunta":"¿Cuál es la diferencia entre Data Science y análisis de datos?","respuesta":"El análisis de datos ayuda a interpretar información y elaborar informes. Data Science incorpora además estadística, programación y modelos de Machine Learning para explorar patrones y realizar predicciones a partir de los datos."},{"pregunta":"¿Cuál es la salida laboral de Data Science?","respuesta":"La formación se vincula con tareas de análisis, visualización e inteligencia de negocio en empresas tecnológicas, consultoras y áreas que usan datos para tomar decisiones. También permite participar en proyectos de analítica de manera independiente."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Redes Informáticas?","respuesta":"Estudiás fundamentos e interconexión de redes, servidores, servicios de red, scripting y automatización. La formación también incluye seguridad y gestión de redes para administrar la conectividad de una organización."},{"pregunta":"¿Qué hace un técnico en Redes Informáticas?","respuesta":"Configura y administra redes de datos, servidores y servicios de conectividad. Puede trabajar con direccionamiento IP, switching y routing, además de automatizar tareas de gestión de la infraestructura informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y Seguridad Informática?","respuesta":"Redes Informáticas se centra en la conectividad y la administración de redes y servidores. Seguridad Informática profundiza la protección de sistemas y datos, el análisis de riesgos y la respuesta ante amenazas. Las dos carreras comparten contenidos de redes."},{"pregunta":"¿Necesito conocimientos previos o saber programar para estudiar Redes Informáticas?","respuesta":"No. La carrera está pensada para comenzar desde cero y avanzar progresivamente en redes, lógica de programación, scripting y seguridad informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y soporte IT?","respuesta":"El soporte IT se enfoca en resolver problemas de equipos y sistemas, mientras que Redes Informáticas se centra en la conectividad y la infraestructura que permite que los dispositivos y servicios se comuniquen. Los dos campos pueden complementarse dentro de un equipo tecnológico."},{"pregunta":"¿Tiene salida laboral la Tecnicatura en Redes Informáticas?","respuesta":"Sí. Podés desarrollarte en soporte IT, administración de redes e infraestructura tecnológica, en compañías de tecnología, organizaciones con áreas de IT, centros de datos y proveedores de servicios informáticos que necesitan mantener sus sistemas conectados y funcionando."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. La carrera contempla el certificado intermedio de Asistente en Redes Informáticas, que acredita una etapa de la formación antes de completar el título final."},{"pregunta":"¿Qué título obtengo al finalizar?","respuesta":"El título oficial de Técnico Superior en Redes Informáticas, con validez nacional. La tecnicatura dura 2 años y se cursa 100% online."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con Ingeniería en Software y con la Licenciatura en Informática de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 220 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Redes Informáticas?","respuesta":"Estudiás fundamentos e interconexión de redes, servidores, servicios de red, scripting y automatización. La formación también incluye seguridad y gestión de redes para administrar la conectividad de una organización."},{"pregunta":"¿Qué hace un técnico en Redes Informáticas?","respuesta":"Configura y administra redes de datos, servidores y servicios de conectividad. Puede trabajar con direccionamiento IP, switching y routing, además de automatizar tareas de gestión de la infraestructura informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y Seguridad Informática?","respuesta":"Redes Informáticas se centra en la conectividad y la administración de redes y servidores. Seguridad Informática profundiza la protección de sistemas y datos, el análisis de riesgos y la respuesta ante amenazas. Las dos carreras comparten contenidos de redes."},{"pregunta":"¿Necesito conocimientos previos o saber programar para estudiar Redes Informáticas?","respuesta":"No. La carrera está pensada para comenzar desde cero y avanzar progresivamente en redes, lógica de programación, scripting y seguridad informática."},{"pregunta":"¿Cuál es la diferencia entre Redes Informáticas y soporte IT?","respuesta":"El soporte IT se enfoca en resolver problemas de equipos y sistemas, mientras que Redes Informáticas se centra en la conectividad y la infraestructura que permite que los dispositivos y servicios se comuniquen. Los dos campos pueden complementarse dentro de un equipo tecnológico."},{"pregunta":"¿Tiene salida laboral la Tecnicatura en Redes Informáticas?","respuesta":"Sí. Podés desarrollarte en soporte IT, administración de redes e infraestructura tecnológica, en compañías de tecnología, organizaciones con áreas de IT, centros de datos y proveedores de servicios informáticos que necesitan mantener sus sistemas conectados y funcionando."},{"pregunta":"¿Tiene certificado intermedio?","respuesta":"Sí. La carrera contempla el certificado intermedio de Asistente en Redes Informáticas, que acredita una etapa de la formación antes de completar el título final."},{"pregunta":"¿Qué título obtengo al finalizar?","respuesta":"El título oficial de Técnico Superior en Redes Informáticas, con validez nacional. La tecnicatura dura 2 años y se cursa 100% online."}]}]';
UPDATE carreras SET slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Seguridad Informática?","respuesta":"Estudiás seguridad de redes y servidores, programación y scripting, riesgos, operaciones de seguridad y análisis de ataques. La formación se orienta a proteger sistemas y datos y a detectar vulnerabilidades."},{"pregunta":"¿Qué hace un técnico en Seguridad Informática?","respuesta":"Participa en la protección de sistemas, el monitoreo de amenazas y la identificación de vulnerabilidades. También puede colaborar en el análisis de incidentes y la aplicación de controles para reducir riesgos de seguridad."},{"pregunta":"¿Cuál es la salida laboral de Seguridad Informática?","respuesta":"La formación se relaciona con tareas en áreas de informática y ciberseguridad, consultoras y equipos internos de seguridad. Incluye monitoreo, protección de información y respuesta ante incidentes en organizaciones que necesitan cuidar sus sistemas y datos."},{"pregunta":"¿Cuánto dura la tecnicatura y cómo se cursa?","respuesta":"Dura 2 años, organizados en cuatro cuatrimestres. Se cursa 100% online, con clases en vivo que quedan grabadas, laboratorios virtuales y actividades prácticas."},{"pregunta":"¿Qué título obtengo al terminar?","respuesta":"El de Técnico Superior en Seguridad Informática, un título oficial con acreditación nacional. Al terminar el primer año obtenés además el certificado intermedio de Auxiliar en Administración de Seguridad Informática."},{"pregunta":"¿Necesito conocimientos previos?","respuesta":"No. La carrera arranca desde cero, con Fundamento de redes y Lógica de programación en el primer cuatrimestre, y avanza paso a paso hacia la seguridad de sistemas y redes."},{"pregunta":"¿Cuál es la diferencia entre seguridad informática y ciberseguridad?","respuesta":"La seguridad informática abarca la protección de sistemas, redes y datos. La ciberseguridad pone el foco en prevenir, detectar y responder ante amenazas e incidentes digitales. Son campos muy cercanos y en el trabajo comparten herramientas y tareas; la carrera forma en los dos."},{"pregunta":"¿Tiene prácticas?","respuesta":"Sí. En el último cuatrimestre hacés Práctica profesional I y II, donde aplicás lo aprendido sobre redes, riesgos y operaciones de seguridad a situaciones de trabajo."},{"pregunta":"¿Puedo seguir estudiando en Universidad Siglo 21 después?","respuesta":"Sí. El título articula con la Licenciatura en Seguridad Informática y Ciberseguridad de Universidad Siglo 21. Podés ver qué materias se reconocen en el simulador de equivalencias de Siglo 21."}]}]' WHERE id = 221 AND slides = '[{"type":"faq","items":[{"pregunta":"¿Qué se aprende en la Tecnicatura en Seguridad Informática?","respuesta":"Estudiás seguridad de redes y servidores, programación y scripting, riesgos, operaciones de seguridad y análisis de ataques. La formación se orienta a proteger sistemas y datos y a detectar vulnerabilidades."},{"pregunta":"¿Qué hace un técnico en Seguridad Informática?","respuesta":"Participa en la protección de sistemas, el monitoreo de amenazas y la identificación de vulnerabilidades. También puede colaborar en el análisis de incidentes y la aplicación de controles para reducir riesgos de seguridad."},{"pregunta":"¿Cuál es la salida laboral de Seguridad Informática?","respuesta":"La formación se relaciona con tareas en áreas de informática y ciberseguridad, consultoras y equipos internos de seguridad. Incluye monitoreo, protección de información y respuesta ante incidentes en organizaciones que necesitan cuidar sus sistemas y datos."}]}]';
